import os


def read_rows(path, delimiter=","):
    if not os.path.exists(path):
        raise FileNotFoundError("input not found: " + path)
    with open(path, encoding="utf-8") as fh:
        return [line.rstrip("\n").split(delimiter) for line in fh]

