from src.filter import drop_empty


def test_drop_empty():
    rows = [["a", "b"], ["", ""], ["c", "d"]]
    assert drop_empty(rows) == [["a", "b"], ["c", "d"]]


def test_drop_empty_all_empty():
    rows = [["", ""], ["", ""]]
    assert drop_empty(rows) == []


def test_drop_empty_none_empty():
    rows = [["a", "b"], ["c", "d"]]
    assert drop_empty(rows) == [["a", "b"], ["c", "d"]]


def test_drop_empty_preserves_order():
    rows = [["x", ""], ["", ""], ["y", "z"], ["", ""]]
    assert drop_empty(rows) == [["x", ""], ["y", "z"]]


def test_drop_empty_single_non_empty_cell():
    rows = [["", ""], ["a", ""], ["", ""]]
    assert drop_empty(rows) == [["a", ""]]

